<?php namespace App\Features\Admin\Livewire;use Livewire\Component;use App\Models\User;use App\Features\Admin\Services\AdminUserService;class AdminUserStockList extends Component{public User $user;public function mount(User $user){$this->user=$user;}public function render(){return view('livewire.admin.admin-user-stock-list',['stocks'=>app(AdminUserService::class)->stocksFor($this->user)])->layout('components.layouts.app');}}